-- Binärfragen (5 Stück)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Ist-Analyse ohne direkte Beteiligung der betroffenen Mitarbeiter immer unvollständig?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumente und Beobachtungen können ausreichen, sind aber weniger präzise"}, {"text": "Ja", "correct": false, "because": "Mitarbeiterbeteiligung ist hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Ist-Analyse allein die zukünftigen Anforderungen eines Prozesses vollständig definieren?', 2, '[{"text": "Nein", "correct": true, "because": "Sie beschreibt den Ist-Zustand, nicht den Soll-Zustand"}, {"text": "Ja", "correct": false, "because": "Zukünftige Bedürfnisse erfordern zusätzliche Analysen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Geschäftsprozesse eines Unternehmens in einer Ist-Analyse abgebildet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf relevanten Prozessen für das Projekt"}, {"text": "Ja", "correct": false, "because": "Vollständigkeit ist nicht immer erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Dokumentation von Arbeitsabläufen in einer Ist-Analyse wichtiger als deren Analyse?', 2, '[{"text": "Nein", "correct": true, "because": "Analyse identifiziert Schwachstellen, Dokumentation ist Mittel"}, {"text": "Ja", "correct": false, "because": "Dokumentation ohne Analyse ist unzureichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Ist-Analyse ohne technische Hilfsmittel wie Software effektiv durchgeführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Manuelle Methoden wie Interviews sind möglich"}, {"text": "Nein", "correct": false, "because": "Tools sind hilfreich, aber nicht zwingend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist am besten geeignet, um in einer Ist-Analyse verborgene Schwachstellen in Geschäftsprozessen aufzudecken?', 3, '[{"text": "Interviews mit Mitarbeitern", "correct": true, "because": "Direkte Einblicke zeigen reale Probleme"}, {"text": "Analyse der Unternehmensbilanz", "correct": false, "because": "Finanzen zeigen keine Prozessdetails"}, {"text": "Vergleich mit Mitbewerbern", "correct": false, "because": "Externer Fokus hilft nicht beim Ist-Zustand"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel einer Ist-Analyse im Kontext eines IT-Projekts?', 2, '[{"text": "Verständnis der aktuellen Abläufe schaffen", "correct": true, "because": "Basis für Optimierung und Anforderungen"}, {"text": "Kosten sofort reduzieren", "correct": false, "because": "Kostenreduktion ist Folge, kein Ziel"}, {"text": "Neue Softwarelösungen vorschlagen", "correct": false, "because": "Vorschläge kommen später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt wird in einer Ist-Analyse am wenigsten berücksichtigt?', 3, '[{"text": "Zukünftige Markttrends", "correct": true, "because": "Fokus liegt auf dem aktuellen Zustand"}, {"text": "Existierende Arbeitsabläufe", "correct": false, "because": "Kern der Analyse"}, {"text": "Technische Einschränkungen", "correct": false, "because": "Wird oft einbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug ist für die Visualisierung einer Ist-Analyse am häufigsten verwendet?', 2, '[{"text": "Flussdiagramme", "correct": true, "because": "Zeigen Abläufe klar und strukturiert"}, {"text": "Tabellenkalkulation", "correct": false, "because": "Weniger geeignet für Prozessdarstellung"}, {"text": "Textdokumente", "correct": false, "because": "Bieten keine visuelle Übersicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler wird bei einer Ist-Analyse oft übersehen?', 3, '[{"text": "Ineffiziente manuelle Schritte", "correct": true, "because": "Gewohnheiten werden nicht hinterfragt"}, {"text": "Zu schnelle Prozessdurchführung", "correct": false, "because": "Kein typischer Fehler"}, {"text": "Automatische Fehlerkorrektur", "correct": false, "because": "Nicht realistisch"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten in einer Ist-Analyse detailliert beschrieben werden?', 4, '[{"text": "Abfolge der Arbeitsschritte", "correct": true, "because": "Zeigt den Prozessverlauf"}, {"text": "Verantwortliche Personen", "correct": true, "because": "Klärt Zuständigkeiten"}, {"text": "Zukünftige Verbesserungsvorschläge", "correct": false, "because": "Gehört zur Soll-Analyse"}, {"text": "Eingesetzte Technologien", "correct": true, "because": "Beeinflusst Abläufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden sind für die Erhebung einer Ist-Analyse sinnvoll?', 3, '[{"text": "Beobachtung vor Ort", "correct": true, "because": "Liefert realistische Einblicke"}, {"text": "Fragebögen an Mitarbeiter", "correct": true, "because": "Erfahrungen der Beteiligten"}, {"text": "Analyse von Wettbewerberdaten", "correct": false, "because": "Extern und nicht Ist-Zustand"}, {"text": "Workshops mit Stakeholdern", "correct": true, "because": "Fördert Diskussion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei einer unzureichenden Ist-Analyse auftreten?', 4, '[{"text": "Missverständnisse über Anforderungen", "correct": true, "because": "Fehlendes Verständnis führt zu Fehlern"}, {"text": "Unrealistische Zeitpläne", "correct": true, "because": "Prozessdauer wird unterschätzt"}, {"text": "Schnellere Projektumsetzung", "correct": false, "because": "Gegenteil ist der Fall"}, {"text": "Verpasste Optimierungspotenziale", "correct": true, "because": "Schwachstellen bleiben unentdeckt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert eine Ist-Analyse für die weitere Projektplanung?', 3, '[{"text": "Aktuelle Prozessdauer", "correct": true, "because": "Basis für Zeitplanung"}, {"text": "Technische Abhängigkeiten", "correct": true, "because": "Beeinflusst Lösungsdesign"}, {"text": "Künftige Marktchancen", "correct": false, "because": "Nicht Teil des Ist-Zustands"}, {"text": "Bestehende Engpässe", "correct": true, "because": "Zeigt Verbesserungsbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Durchführung einer Ist-Analyse entstehen?', 3, '[{"text": "Widerstand der Mitarbeiter", "correct": true, "because": "Änderungsangst kann Kooperation erschweren"}, {"text": "Fehlende Dokumentation", "correct": true, "because": "Erschwert den Überblick"}, {"text": "Zu schnelle Datenerfassung", "correct": false, "because": "Geschwindigkeit ist kein Problem"}, {"text": "Ungenaue Zeitangaben", "correct": true, "because": "Subjektive Einschätzungen verfälschen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Ist-Analyse sollte alle Prozesse eines Unternehmens abdecken. b) Sie dient als Grundlage für die Soll-Analyse.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Nicht alle Prozesse sind relevant, aber sie ist Basis für den Soll-Zustand"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Ist-Analyse identifiziert ineffiziente Prozesse. b) Sie ersetzt die Notwendigkeit von Kundenanforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ineffizienzen werden erkannt, Anforderungen bleiben essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Ist-Analyse kann durch historische Daten allein erstellt werden. b) Direkte Beobachtung verbessert ihre Genauigkeit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Daten reichen nicht, Beobachtung liefert Kontext"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Ist-Analyse sollte technische Details der aktuellen Systeme ignorieren. b) Sie hilft, den Ressourcenbedarf eines Projekts abzuschätzen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Technik ist relevant, Ressourcen werden klarer"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Ist-Analyse kann Schwächen in der Kommunikation zwischen Abteilungen aufdecken. b) Sie ist nur dann nützlich, wenn sie sofort optimiert wird.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation wird sichtbar, Optimierung folgt später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

